// V1 "Layer Atlas": the layer stack as React Flow bands, built purely from graph.json.
// WHY derived, never placed: graph.json is regenerated by the linter lane and will grow (criterion fr5). Bands come from
// LAYER_ORDER; inside the bands a small layered (Sugiyama-style) layout orders and places nodes, and long edges get
// "dummy" waypoints in every band they cross so they run between boxes instead of through them (with 10 of 15 deps
// landing on robot_msgs, centred rows drew one thick line straight through every singleton band).
import { layersOf, packageEdges, typeEdges, LAYER_LABEL, LAYER_BLURB } from "@shared/graph.js";

export const NODE_W = 168, NODE_H = 46, GAP = 18, ROW_GAP = 30, PAD_Y = 9, GUTTER = 132, PAD_R = 18, BAND_GAP = 28, COLLAPSED_H = 44;
const DUMMY_W = 10, DUMMY_GAP = 10;
export const TYPES_DEFAULT = 8; // the most-used types shown before "+N more"

export const bandId = (key) => "band:" + key;

// Use counts per type (all kinds), most used first: picks the default visible types and the type index order.
export function typeRanking(graph, kinds = null) {
  const n = new Map(graph.types.map((t) => [t.id, 0]));
  for (const u of graph.uses) if (!kinds || kinds.has(u.kind)) n.set(u.type, (n.get(u.type) || 0) + 1);
  return [...n.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).map(([id, count]) => ({ id, count }));
}

export function bandsOf(graph, lens, showAgents) {
  const out = [];
  for (const l of layersOf(graph)) {
    out.push({ key: l, kind: "layer", label: LAYER_LABEL[l] || l, blurb: LAYER_BLURB[l] || "" });
    if (l === "vocabulary" && lens === "types") out.push({ key: "types", kind: "types", label: "types", blurb: "robot_msgs types. Green: a package produces it (public return). Blue: a package consumes it (public parameter)." });
  }
  if (lens === "types" && !out.some((b) => b.key === "types")) out.unshift({ key: "types", kind: "types", label: "types", blurb: "robot_msgs types" });
  if (showAgents && (graph.agents || []).length) out.push({ key: "agents", kind: "agents", label: "agents", blurb: "Agents build on packages; a package never imports an agent." });
  return out; // bottom -> top
}

const widthOf = (id) => id.startsWith("d:") ? DUMMY_W : NODE_W;
const sep = (a, b) => (widthOf(a) + widthOf(b)) / 2 + (a.startsWith("d:") && b.startsWith("d:") ? DUMMY_GAP : a.startsWith("d:") || b.startsWith("d:") ? 12 : GAP);

// opts: { lens: "packages"|"types", showImports, showDeps, showAgents, allTypes, collapsed: Set<bandKey>, selected, hoverEdge }
export function buildStack(graph, opts) {
  const { lens, showImports, showDeps, showAgents, allTypes, collapsed, selected, hoverEdge, perRow = 7, typesPerRow = 8 } = opts;
  const bands = bandsOf(graph, lens, showAgents);
  const bandIndex = Object.fromEntries(bands.map((b, i) => [b.key, i]));
  const pkgIds = new Set(graph.packages.map((p) => p.id));

  // ---- which types are visible: the most-used first; the rest merge into one "+N more" node
  // Default types: most uses of the kinds on screen (with imports hidden, a type used only internally draws no edge).
  const kinds = new Set(["produces", "consumes", ...(showImports ? ["imports"] : [])]);
  const ranking = typeRanking(graph, kinds);
  const usedRanking = ranking.filter((r) => r.count > 0);
  const tEdges = lens === "types" ? typeEdges(graph).filter((e) => kinds.has(e.kind)) : [];
  const shownTypeIds = allTypes ? ranking.map((r) => r.id) : usedRanking.slice(0, TYPES_DEFAULT).map((r) => r.id);
  const shownTypes = new Set(shownTypeIds);
  const hiddenTypes = ranking.filter((r) => !shownTypes.has(r.id));
  const typeById = Object.fromEntries(graph.types.map((t) => [t.id, t]));
  const typeUseCount = Object.fromEntries(typeRanking(graph).map((r) => [r.id, r.count]));
  const typePkgs = {};
  for (const u of graph.uses) (typePkgs[u.type] ||= new Set()).add(u.package);
  const pkgUses = {};
  for (const u of graph.uses) pkgUses[u.package] = (pkgUses[u.package] || 0) + 1;

  // ---- items per band
  const items = {};
  for (const b of bands) items[b.key] = [];
  for (const p of graph.packages) items[p.layer]?.push({ id: "pkg:" + p.id, kind: "pkg", ref: p });
  if (lens === "types") {
    for (const id of shownTypeIds) if (typeById[id]) items.types.push({ id: "type:" + id, kind: "type", ref: typeById[id] });
    if (hiddenTypes.length) items.types.push({ id: "type-more", kind: "more", count: hiddenTypes.length });
    else if (allTypes && usedRanking.length > TYPES_DEFAULT) items.types.push({ id: "type-less", kind: "less" });
  }
  if (showAgents) for (const a of graph.agents || []) items.agents.push({ id: "agent:" + a.id, kind: "agent", ref: a });

  // ---- raw edges between original items
  const raw = [];
  if (showDeps) for (const e of packageEdges(graph)) if (e.known) raw.push({ kind: e.required ? "dep" : "extra", s: "pkg:" + e.source, t: "pkg:" + e.target, n: 1, extras: e.extras, rows: [] });
  for (const e of tEdges) {
    const typeEnd = shownTypes.has(e.type) ? "type:" + e.type : "type-more";
    const pkg = "pkg:" + e.package;
    if (!pkgIds.has(e.package)) continue;
    if (e.kind === "consumes") raw.push({ kind: "consumes", s: typeEnd, t: pkg, n: e.rows.length, orig: ["type:" + e.type, pkg], rows: e.rows });
    else raw.push({ kind: e.kind, s: pkg, t: typeEnd, n: e.rows.length, orig: [pkg, "type:" + e.type], rows: e.rows });
  }
  if (showAgents) for (const a of graph.agents || []) for (const p of a.builds_on || []) if (pkgIds.has(p)) raw.push({ kind: "builds", s: "agent:" + a.id, t: "pkg:" + p, n: 1, rows: [] });

  // ---- ranks: one per row of each band, bottom-up
  const ranks = []; // [{band, row, ids: []}]
  const rankOf = new Map();
  for (const b of bands) {
    const pr = b.key === "types" ? typesPerRow : perRow;
    const list = items[b.key];
    const rows = Math.max(1, Math.ceil(list.length / pr));
    // multi-row bands: the bottom row holds the first chunk (for types: the most used, nearest robot_msgs)
    for (let r = 0; r < rows; r++) {
      const ids = list.slice(r * pr, (r + 1) * pr).map((it) => it.id);
      const rank = { band: b.key, row: r, rows, ids };
      for (const id of ids) rankOf.set(id, ranks.length);
      ranks.push(rank);
    }
  }

  // ---- dummy waypoints for edges spanning more than one rank. Edges sharing their upper end and kind share one lane
  // (bundled), so sim2real's dozens of type edges run down as one green and one blue line and fan out only at the end.
  const adj = new Map(); // layered neighbours (including dummies)
  const linked = new Set();
  const link = (a, b) => {
    const k = a < b ? a + "|" + b : b + "|" + a; if (linked.has(k)) return; linked.add(k);
    (adj.get(a) || adj.set(a, []).get(a)).push(b); (adj.get(b) || adj.set(b, []).get(b)).push(a);
  };
  raw.forEach((e) => {
    const rs = rankOf.get(e.s), rt = rankOf.get(e.t);
    e.route = [];
    // WHY: an edge inside one row (e.g. a vocabulary package's extra on another vocabulary package) has no rank to
    // cross; stepping toward it would never arrive and ran off the end of ranks[].
    if (rs == null || rt == null || rs === rt) return;
    const step = rt > rs ? 1 : -1;
    const upper = rs > rt ? e.s : e.t;
    const lane = `${upper}~${e.kind === "extra" ? "dep" : e.kind}`;
    let prev = e.s;
    for (let r = rs + step; r !== rt; r += step) {
      const d = `d:${lane}:${r}`;
      if (!rankOf.has(d)) { ranks[r].ids.push(d); rankOf.set(d, r); }
      e.route.push(d);
      link(prev, d); prev = d;
    }
    link(prev, e.t);
  });

  // ---- order inside ranks: barycentre sweeps (down then up), "+N more" pinned at the end
  const x = new Map();
  const pack = (rank) => {
    let cur = 0;
    rank.ids.forEach((id, i) => { if (i) cur += sep(rank.ids[i - 1], id); x.set(id, cur); });
    const shift = -cur / 2;
    for (const id of rank.ids) x.set(id, x.get(id) + shift);
  };
  ranks.forEach(pack);
  const pinned = (id) => id === "type-more" || id === "type-less";
  const orderBy = (rank, nbRank) => {
    const score = (id) => {
      const xs = (adj.get(id) || []).filter((n) => rankOf.get(n) === nbRank).map((n) => x.get(n));
      return xs.length ? xs.reduce((a, c) => a + c, 0) / xs.length : x.get(id);
    };
    const body = rank.ids.filter((id) => !pinned(id)).map((id, i) => ({ id, s: score(id), i }));
    body.sort((a, c) => a.s - c.s || a.i - c.i);
    rank.ids = [...body.map((b) => b.id), ...rank.ids.filter(pinned)];
    pack(rank);
  };
  for (let sweep = 0; sweep < 6; sweep++) {
    for (let r = 1; r < ranks.length; r++) orderBy(ranks[r], r - 1);
    for (let r = ranks.length - 2; r >= 0; r--) orderBy(ranks[r], r + 1);
  }

  // ---- x: pull every node toward its neighbours' mean, never overlapping, order kept
  for (let it = 0; it < 40; it++) {
    for (const rank of ranks) {
      const ids = rank.ids;
      const want = ids.map((id) => {
        const xs = (adj.get(id) || []).map((n) => x.get(n));
        return xs.length ? xs.reduce((a, c) => a + c, 0) / xs.length : x.get(id);
      });
      const F = [], B = [];
      ids.forEach((id, i) => { F[i] = i ? Math.max(want[i], F[i - 1] + sep(ids[i - 1], id)) : want[i]; });
      for (let i = ids.length - 1; i >= 0; i--) B[i] = i < ids.length - 1 ? Math.min(want[i], B[i + 1] - sep(ids[i], ids[i + 1])) : want[i];
      ids.forEach((id, i) => x.set(id, (F[i] + B[i]) / 2));
    }
  }
  let minX = Infinity, maxX = -Infinity;
  for (const [id, v] of x) { minX = Math.min(minX, v - widthOf(id) / 2); maxX = Math.max(maxX, v + widthOf(id) / 2); }
  const offset = GUTTER + 14 - minX;
  for (const [id, v] of x) x.set(id, v + offset);
  const W = Math.max(maxX - minX + GUTTER + 14 + PAD_R, 560);

  // ---- band geometry, bottom-up (React Flow y grows downward, so the bottom band has the largest y)
  const geo = {};
  let y = 0;
  for (const b of bands) {
    const isCollapsed = collapsed.has(b.key);
    const rows = ranks.filter((r) => r.band === b.key).length;
    const h = isCollapsed ? COLLAPSED_H : rows * NODE_H + (rows - 1) * ROW_GAP + 2 * PAD_Y;
    y -= h;
    geo[b.key] = { y, h, collapsed: isCollapsed, rows };
    y -= BAND_GAP;
  }
  // row 0 is the bottom row of a band
  const rowTop = (band, row) => geo[band].y + PAD_Y + (geo[band].rows - 1 - row) * (NODE_H + ROW_GAP);

  // ---- visible id of every original id (a collapsed band stands in for its members)
  const vis = new Map();
  for (const b of bands) for (const it of items[b.key]) vis.set(it.id, collapsed.has(b.key) ? bandId(b.key) : it.id);
  if (lens === "types") for (const h of hiddenTypes) vis.set("type:" + h.id, collapsed.has("types") ? bandId("types") : "type-more");
  const bandOfVis = new Map();
  for (const b of bands) { bandOfVis.set(bandId(b.key), b.key); for (const it of items[b.key]) bandOfVis.set(it.id, b.key); }

  // ---- aggregate edges on visible endpoints
  const agg = new Map();
  for (const e of raw) {
    const s = vis.get(e.s), t = vis.get(e.t);
    if (!s || !t || s === t) continue;
    const key = `${e.kind === "extra" ? "dep" : e.kind}|${s}|${t}`;
    if (!agg.has(key)) agg.set(key, { key, kind: e.kind, s, t, n: 0, links: 0, extras: new Set(), ends: new Set(), rows: [], route: e.route, sxs: [], txs: [] });
    const a = agg.get(key);
    if (e.kind === "dep") a.kind = "dep";
    a.n += e.n; a.links += 1;
    for (const xx of e.extras || []) a.extras.add(xx);
    for (const end of [e.s, e.t, ...(e.orig || [])]) a.ends.add(end);
    a.rows.push(...e.rows);
    a.sxs.push(x.get(e.s)); a.txs.push(x.get(e.t));
  }

  // ---- focus
  const selVis = selected ? vis.get(selected) || selected : null;
  const hotEdges = new Set(), near = new Set();
  if (selected) {
    near.add(selVis);
    for (const a of agg.values()) if (a.ends.has(selected)) { hotEdges.add(a.key); near.add(a.s); near.add(a.t); }
  }

  // ---- nodes
  const nodes = [];
  for (const b of bands) {
    const g = geo[b.key];
    const members = items[b.key].filter((it) => it.kind !== "more" && it.kind !== "less");
    nodes.push({
      id: bandId(b.key), type: "band", position: { x: 0, y: g.y }, draggable: false, selectable: false, zIndex: -1,
      style: { width: W, height: g.h },
      data: {
        key: b.key, kind: b.kind, label: b.label, blurb: b.blurb, collapsed: g.collapsed,
        count: b.kind === "types" ? `${shownTypeIds.length}/${graph.types.length}` : String(members.length),
        members: g.collapsed ? (b.kind === "types" ? [...members.map((m) => m.ref.name), ...(hiddenTypes.length ? [`+${hiddenTypes.length} more`] : [])] : members.map((m) => m.ref.name ?? m.ref.id)) : null,
        dim: selected ? !near.has(bandId(b.key)) : false,
        hot: selVis === bandId(b.key),
      },
    });
    if (g.collapsed) continue;
    for (const it of items[b.key]) {
      const r = ranks[rankOf.get(it.id)];
      const base = { id: it.id, parentId: bandId(b.key), draggable: false, position: { x: x.get(it.id) - NODE_W / 2, y: rowTop(b.key, r.row) - g.y } };
      const dim = selected ? !near.has(it.id) : false;
      const hot = selVis === it.id;
      if (it.kind === "pkg") {
        const p = it.ref;
        nodes.push({ ...base, type: "pkg", data: { pkg: p, dim, hot, sub: `v${p.version} · lint ${p.lint}`, badge: pkgUses[p.id] ? `${pkgUses[p.id]} uses` : null } });
      } else if (it.kind === "type") {
        const t = it.ref;
        nodes.push({ ...base, type: "type", data: { type: t, dim, hot, sub: `${typeUseCount[t.id] || 0} uses · ${typePkgs[t.id]?.size || 0} pkgs` } });
      } else if (it.kind === "agent") {
        nodes.push({ ...base, type: "agent", data: { agent: it.ref, dim, hot } });
      } else {
        nodes.push({ ...base, type: "more", data: { kind: it.kind, count: it.count, dim: selected ? !near.has(it.id) : false } });
      }
    }
  }

  // ---- edges
  const edges = [];
  const bIdx = (visId) => bandIndex[bandOfVis.get(visId)] ?? 0;
  for (const a of agg.values()) {
    // source sits above target: by band, then by row inside a multi-row band; same row = arc over the top
    const rk = (v) => rankOf.get(v) ?? -1;
    const sameRow = bIdx(a.s) === bIdx(a.t) && (rk(a.s) === rk(a.t) || a.s.startsWith("band:") || a.t.startsWith("band:"));
    const up = bIdx(a.s) > bIdx(a.t) || (bIdx(a.s) === bIdx(a.t) && rk(a.s) > rk(a.t));
    const hot = hotEdges.has(a.key);
    const dim = selected ? !hot : false;
    const intoBand = a.s.startsWith("band:") || a.t.startsWith("band:") || a.s === "type-more" || a.t === "type-more";
    const id = "e:" + a.key;
    const isType = a.kind === "produces" || a.kind === "consumes" || a.kind === "imports";
    const width = isType ? Math.min(4.5, 1.4 + Math.log2(a.n) * 0.7) : 1.6;
    const style = edgeStyleLocal(a.kind, { dim, hot });
    style.strokeWidth = hot || hoverEdge === id ? width + 1 : width;
    if (hoverEdge === id) style.opacity = 1;
    if (lens === "types" && (a.kind === "dep" || a.kind === "extra") && !hot) style.opacity = dim ? 0.06 : 0.3;
    // waypoints of the route that are still on screen (a folded band hides its dummies)
    // A folded end keeps its member's x (mean when several merge), so edges land where the package was.
    const mean = (xs) => xs.filter((v) => v != null).reduce((m, v, i, arr) => m + v / arr.length, 0);
    const sFold = a.s.startsWith("band:"), tFold = a.t.startsWith("band:");
    const points = (a.route || []).map((d) => {
      const r = ranks[rankOf.get(d)];
      if (geo[r.band].collapsed) return null;
      const top = rowTop(r.band, r.row);
      return { x: x.get(d), top, bot: top + NODE_H };
    }).filter(Boolean);
    let label = null;
    const unit = isType ? (a.n === 1 ? "use" : "uses") : a.kind === "builds" ? "" : (a.links === 1 ? "dep" : "deps");
    if (hoverEdge === id) label = edgeText(a, unit);
    else if (intoBand && a.links > 1 && !dim) label = isType ? `${a.links} ${a.s === "type-more" || a.t === "type-more" ? "types" : "pkgs"} · ${a.n} uses` : `${a.links} ${unit}`;
    else if (hot && isType) label = String(a.n);
    edges.push({
      id, source: a.s, target: a.t, sourceHandle: sameRow ? "ts" : up ? "bs" : "ts", targetHandle: sameRow ? "t" : up ? "t" : "b",
      type: "routed", zIndex: hot ? 6 : 2, style, interactionWidth: 14,
      markerEnd: dim ? undefined : `v1-arrow-${a.kind === "extra" ? "dep" : a.kind}`,
      label, labelStyle: { fontSize: 11, fill: "var(--ink)", fontFamily: "var(--mono)" },
      labelBgStyle: { fill: "var(--card)", stroke: "var(--line)" }, labelBgPadding: [5, 2], labelBgBorderRadius: 5,
      data: { points, up, arc: sameRow, dx: a.kind === "produces" ? -6 : a.kind === "consumes" ? 6 : 0, sx: sFold ? mean(a.sxs) : null, tx: tFold ? mean(a.txs) : null, labelAt: intoBand && hoverEdge !== id ? (sFold || a.s === "type-more" ? "source" : "target") : null, labelDy: a.kind === "consumes" ? 17 : 0 },
    });
  }
  return { nodes, edges, W, H: -y - BAND_GAP, bands, hiddenTypes: hiddenTypes.length, shownTypes: shownTypeIds.length };
}

function edgeText(a, unit) {
  const nm = (id) => id.startsWith("band:") ? id.slice(5) + " (folded)" : id === "type-more" ? "other types" : id.replace(/^(pkg|type|agent):/, "").split(".").pop();
  if (a.kind === "dep") return `${nm(a.s)} requires ${nm(a.t)}${a.links > 1 ? ` · ${a.links} ${unit}` : ""}${a.extras.size ? ` (extras: ${[...a.extras].join(", ")})` : ""}`;
  if (a.kind === "extra") return `${nm(a.s)} → ${nm(a.t)} · optional extra [${[...a.extras].join(", ")}]`;
  if (a.kind === "builds") return `agent ${nm(a.s)} builds on ${nm(a.t)}`;
  const verified = a.rows.filter((r) => r.declared && r.verified).length;
  const line = a.kind === "consumes" ? `${nm(a.t)} consumes ${nm(a.s)}` : `${nm(a.s)} ${a.kind === "imports" ? "imports" : "produces"} ${nm(a.t)}`;
  return `${line} · ${a.n} ${unit} · ${verified} declared+verified`;
}

// Same colour vocabulary as @shared/parts.jsx edgeStyle; local so dimming also drops the arrowhead.
const COLOR = { produces: "var(--produce)", consumes: "var(--consume)", imports: "var(--muted)", dep: "var(--dep)", extra: "var(--dep)", builds: "var(--agent)" };
function edgeStyleLocal(kind, { dim, hot }) {
  const style = { stroke: COLOR[kind] || "var(--muted)", opacity: dim ? 0.1 : hot ? 1 : 0.85 };
  if (kind === "extra" || kind === "imports") style.strokeDasharray = "6 5";
  if (kind === "builds") style.strokeDasharray = "2 4";
  return style;
}
export const MARKER_KINDS = ["produces", "consumes", "imports", "dep", "builds"];

// Path through the waypoints: vertical through each band it crosses, S-curves in the gaps.
export function routedPath({ sourceX, sourceY, targetX, targetY, points, up, arc = false, dx = 0, sx = null, tx = null, labelAt = null, labelDy = 0 }) {
  if (sx != null) sourceX = sx;
  if (tx != null) targetX = tx;
  const pts = [{ x: sourceX + dx, y: sourceY }];
  for (const p of points) { if (up) { pts.push({ x: p.x, y: p.top }, { x: p.x, y: p.bot }); } else { pts.push({ x: p.x, y: p.bot }, { x: p.x, y: p.top }); } }
  pts.push({ x: targetX + dx, y: targetY });
  if (arc) { // both ends on top of the same row: one arch above it
    const a = pts[0], b = pts[pts.length - 1], top = Math.min(a.y, b.y) - 26;
    return { d: `M${a.x},${a.y} C${a.x},${top} ${b.x},${top} ${b.x},${b.y}`, labelX: (a.x + b.x) / 2, labelY: top + 6 };
  }
  let d = `M${pts[0].x},${pts[0].y}`;
  for (let i = 1; i < pts.length; i++) {
    const a = pts[i - 1], b = pts[i];
    if (Math.abs(a.x - b.x) < 0.5) d += ` L${b.x},${b.y}`;
    else { const my = (a.y + b.y) / 2; d += ` C${a.x},${my} ${b.x},${my} ${b.x},${b.y}`; }
  }
  const dir = up ? 1 : -1; // +y when the edge leaves its source downward
  if (labelAt === "source") return { d, labelX: pts[0].x, labelY: pts[0].y + dir * (13 + labelDy) };
  if (labelAt === "target") return { d, labelX: pts[pts.length - 1].x, labelY: pts[pts.length - 1].y - dir * (13 + labelDy) };
  const mid = pts[Math.floor(pts.length / 2)], mid0 = pts[Math.floor(pts.length / 2) - 1] || mid;
  return { d, labelX: (mid.x + mid0.x) / 2, labelY: (mid.y + mid0.y) / 2 };
}

// Wrap width chosen from the data and the box it must fit: try a few row lengths, keep the one that draws largest.
// WHY: 7 leaves in one row made the hero width-bound at ~0.65 zoom (unreadable 9 px labels); at 2x packages a fixed row
// length is wrong either way. Ties go to the longer row (fewer rows, fewer bends).
export function bestPerRow(graph, opts, boxW, boxH) {
  if (!boxW || !boxH) return { perRow: 7, typesPerRow: 8 };
  let best = { perRow: 7, typesPerRow: 8 }, bestZ = -1;
  const nTypes = opts.lens === "types" ? (opts.allTypes ? graph.types.length : TYPES_DEFAULT) + 1 : 0;
  for (let pr = 3; pr <= 10; pr++) {
    const tChoices = nTypes ? [...new Set([1, 2, 3, 4, 5, 6].map((k) => Math.ceil(nTypes / k)).filter((t) => t >= 3 && t <= 12))] : [8];
    for (const tpr of tChoices) {
      const { W, H } = buildStack(graph, { ...opts, selected: null, hoverEdge: null, perRow: pr, typesPerRow: tpr });
      const z = Math.min((boxW - 24) / W, (boxH - 24) / H);
      if (z > bestZ * 1.04) { best = { perRow: pr, typesPerRow: tpr }; bestZ = z; }
    }
  }
  return best;
}

// Ids of the types the type band shows by default for these toggles (used to unfold "+N more" when focusing a hidden one).
export function defaultTypeIds(graph, showImports) {
  const kinds = new Set(["produces", "consumes", ...(showImports ? ["imports"] : [])]);
  return typeRanking(graph, kinds).filter((r) => r.count > 0).slice(0, TYPES_DEFAULT).map((r) => r.id);
}
